// === Tab: mySketch ===
let Shader,canv,coolingMap,tex,
		speed=-2,utime=0;
function setup() {
  canv=createCanvas(windowWidth,windowHeight,WEBGL);
	noStroke().pixelDensity(1).background(0);
	coolingMap=createGraphics(width,height);
	coolingMap.loadPixels();
	for (let y=0;y<height;y++) {for(let x=0;x<width;x++) {coolingMap.pixels[(x+y*width)*4]=pow(noise(x/50,y/50),3)*255;coolingMap.pixels[(x+y*width)*4+3]=255;}}
	coolingMap.updatePixels();
	tex=createGraphics(width,height);
}
function draw() {
 	shader(Shader);
	tex.background(0).image(canv,0,speed,width,height);
	coolingMap.image(coolingMap,0,speed,width,height);
	coolingMap.loadPixels();
	for (let y=abs(speed);y>0;y--) {for(let x=0;x<width;x++) {coolingMap.pixels[(x+(speed<0?-y+height:y)*width)*4]=pow(noise(x/50,((speed<0?-y+height:y)+utime)/50),3)*255;}}
	coolingMap.updatePixels();
	Shader.setUniform('tex',tex);
	Shader.setUniform('coolingMap',coolingMap);
	rect(0,0,width,height);
	utime-=speed;
}
function keyPressed() {
	if (keyCode==40&&speed<4) {speed++;}
	if (keyCode==38&&speed>-4) {speed--;}
}
function preload(){
	Shader=new p5.Shader(this._renderer,`
		precision highp float;
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;
		varying vec2 vTexCoord;
		void main() {
			vTexCoord=aTexCoord;
			vec4 positionVec4=vec4(aPosition,1.);
			positionVec4.xy=positionVec4.xy*2.-1.; 
			gl_Position=positionVec4;
		}
	`,`
		precision highp float;
		varying vec2 vTexCoord;
		const float width=${windowWidth}.;
		var float height=${windowHeight}.;
		uniform sampler2D tex;
		uniform sampler2D coolingMap;
		void main() {
			float x=vTexCoord.x*width;
			float y=height-vTexCoord.y*height;
			float val;
			if (floor(sqrt(pow(x-width/2.,2.)+pow(y-height/2.,2.))/5.)==floor(height/20.)||y>height-5.) {val=1.;} else {
				val=(
				texture2D(tex,vec2(x/width,(y-1.)/height)).r+
				texture2D(tex,vec2((x+1.)/width,y/height)).r+
				texture2D(tex,vec2(x/width,(y+1.)/height)).r+
				texture2D(tex,vec2((x-1.)/width,y/height)).r
				)/4.-texture2D(coolingMap,vec2(x/width,y/height)).r/5.;
			}
			gl_FragColor=vec4(vec3(val,(val-0.3),(val-0.6)),1.);
		}
	`);
}

